import{_ as r,o as t,c as s,an as a}from"./chunks/framework.BAJgIXXb.js";const p=JSON.parse('{"title":"OSINT","description":"Outils et ressources OSINT.","frontmatter":{"title":"OSINT","description":"Outils et ressources OSINT.","aside":false,"prev":false,"next":false},"headers":[],"relativePath":"osint/index.md","filePath":"osint/index.md"}'),o={name:"osint/index.md"};function n(i,e,l,h,c,g){return t(),s("div",null,e[0]||(e[0]=[a('<h1 id="osint" tabindex="-1">OSINT <a class="header-anchor" href="#osint" aria-label="Permalink to &quot;OSINT&quot;">​</a></h1><p>Outils OSINT classés par usage.</p><p><strong><a href="./cheatsheet">Cheatsheet OSINT - commandes à copier</a></strong></p><h2 id="recherche-web-et-dorks" tabindex="-1">Recherche Web et dorks <a class="header-anchor" href="#recherche-web-et-dorks" aria-label="Permalink to &quot;Recherche Web et dorks&quot;">​</a></h2><ul><li><strong><a href="https://www.google.com/" target="_blank" rel="noreferrer">Google</a></strong> - Requêtes avancées avec <code>site:</code>, <code>filetype:</code> et expressions exactes.</li><li><strong><a href="https://www.bing.com/" target="_blank" rel="noreferrer">Bing</a></strong> - Autre index pour comparer les résultats.</li><li><strong><a href="https://search.brave.com/" target="_blank" rel="noreferrer">Brave Search</a></strong> - Moteur complémentaire pour élargir la recherche.</li><li><strong><a href="https://www.qwant.com/" target="_blank" rel="noreferrer">Qwant</a></strong> - Moteur de recherche alternatif.</li><li><strong><a href="https://www.exploit-db.com/google-hacking-database" target="_blank" rel="noreferrer">Google Hacking Database</a></strong> - Exemples d&#39;opérateurs pour une reconnaissance autorisée.</li></ul><h2 id="pseudonymes-et-profils-publics" tabindex="-1">Pseudonymes et profils publics <a class="header-anchor" href="#pseudonymes-et-profils-publics" aria-label="Permalink to &quot;Pseudonymes et profils publics&quot;">​</a></h2><ul><li><strong><a href="https://github.com/sherlock-project/sherlock" target="_blank" rel="noreferrer">Sherlock</a></strong> - Rechercher les comptes liés à un pseudonyme.</li><li><strong><a href="https://github.com/soxoj/maigret" target="_blank" rel="noreferrer">Maigret</a></strong> - Croiser les profils publics et produire un rapport.</li><li><strong><a href="https://github.com/WebBreacher/WhatsMyName" target="_blank" rel="noreferrer">WhatsMyName</a></strong> - Vérifier des pseudonymes sur des plateformes.</li><li><strong><a href="https://github.com/antoniaci/blackbird" target="_blank" rel="noreferrer">Blackbird</a></strong> - Rechercher des comptes publics par pseudonyme ou e-mail.</li><li><strong><a href="https://namechk.com/" target="_blank" rel="noreferrer">Namechk</a></strong> - Vérifier un pseudonyme sur les réseaux sociaux et les domaines.</li><li><strong><a href="https://github.com/qeeqbox/social-analyzer" target="_blank" rel="noreferrer">Social Analyzer</a></strong> - Compléter l&#39;analyse des profils sociaux publics.</li><li><strong><a href="https://www.reddit.com/search/" target="_blank" rel="noreferrer">Reddit Search</a></strong> - Retrouver des publications et commentaires publics.</li><li><strong><a href="https://x.com/search-advanced" target="_blank" rel="noreferrer">X - Recherche avancée</a></strong> - Combiner mots-clés, comptes et périodes lorsque la recherche est disponible.</li></ul><h2 id="reseaux-sociaux" tabindex="-1">Réseaux sociaux <a class="header-anchor" href="#reseaux-sociaux" aria-label="Permalink to &quot;Réseaux sociaux&quot;">​</a></h2><ul><li><strong><a href="https://www.facebook.com/" target="_blank" rel="noreferrer">Facebook</a></strong> - Profils, pages et publications publiques.</li><li><strong><a href="https://www.instagram.com/" target="_blank" rel="noreferrer">Instagram</a></strong> - Profils et publications publics.</li><li><strong><a href="https://www.snapchat.com/" target="_blank" rel="noreferrer">Snapchat</a></strong> - Profils publics et contenus visibles.</li><li><strong><a href="https://www.tiktok.com/" target="_blank" rel="noreferrer">TikTok</a></strong> - Profils et vidéos publics.</li><li><strong><a href="https://www.linkedin.com/" target="_blank" rel="noreferrer">LinkedIn</a></strong> - Profils professionnels et publications.</li><li><strong><a href="https://www.youtube.com/" target="_blank" rel="noreferrer">YouTube</a></strong> - Chaînes, vidéos et descriptions.</li><li><strong><a href="https://x.com/" target="_blank" rel="noreferrer">X</a></strong> - Profils, messages et recherche avancée.</li><li><strong><a href="https://www.threads.net/" target="_blank" rel="noreferrer">Threads</a></strong> - Profils et échanges publics.</li><li><strong><a href="https://bsky.app/" target="_blank" rel="noreferrer">Bluesky</a></strong> - Profils et publications publiques.</li><li><strong><a href="https://mastodon.social/" target="_blank" rel="noreferrer">Mastodon</a></strong> - Profils publics d&#39;une instance.</li><li><strong><a href="https://t.me/" target="_blank" rel="noreferrer">Telegram</a></strong> - Canaux et groupes publics.</li><li><strong><a href="https://www.reddit.com/" target="_blank" rel="noreferrer">Reddit</a></strong> - Publications et commentaires.</li><li><strong><a href="https://www.pinterest.com/" target="_blank" rel="noreferrer">Pinterest</a></strong> - Profils et tableaux publics.</li><li><strong><a href="https://www.twitch.tv/" target="_blank" rel="noreferrer">Twitch</a></strong> - Chaînes et contenus publics.</li><li><strong><a href="https://gitlab.com/" target="_blank" rel="noreferrer">GitLab</a></strong> - Profils et projets techniques publics.</li><li><strong><a href="https://soundcloud.com/" target="_blank" rel="noreferrer">SoundCloud</a></strong> - Profils et contenus audio publics.</li><li><strong><a href="https://steamcommunity.com/" target="_blank" rel="noreferrer">Steam Community</a></strong> - Profils et groupes publics.</li><li><strong><a href="https://vk.com/" target="_blank" rel="noreferrer">VK</a></strong> - Profils et publications publics.</li></ul><h2 id="e-mails-et-exposition" tabindex="-1">E-mails et exposition <a class="header-anchor" href="#e-mails-et-exposition" aria-label="Permalink to &quot;E-mails et exposition&quot;">​</a></h2><ul><li><strong><a href="https://github.com/megadose/holehe" target="_blank" rel="noreferrer">Holehe</a></strong> - Rechercher des indices d&#39;inscription à partir d&#39;un e-mail.</li><li><strong><a href="https://haveibeenpwned.com/" target="_blank" rel="noreferrer">Have I Been Pwned</a></strong> - Vérifier l&#39;apparition d&#39;un e-mail dans des incidents documentés.</li><li><strong><a href="https://emailrep.io/" target="_blank" rel="noreferrer">EmailRep</a></strong> - Consulter des indicateurs de réputation d&#39;une adresse.</li><li><strong><a href="https://hunter.io/" target="_blank" rel="noreferrer">Hunter</a></strong> - Rechercher des adresses et formats d&#39;e-mails professionnels publics.</li></ul><h2 id="domaines-dns-et-sous-domaines" tabindex="-1">Domaines, DNS et sous-domaines <a class="header-anchor" href="#domaines-dns-et-sous-domaines" aria-label="Permalink to &quot;Domaines, DNS et sous-domaines&quot;">​</a></h2><ul><li><strong><a href="https://github.com/laramies/theHarvester" target="_blank" rel="noreferrer">theHarvester</a></strong> - Collecter sous-domaines, e-mails, URL et indices publics.</li><li><strong><a href="https://crt.sh/" target="_blank" rel="noreferrer">crt.sh</a></strong> - Explorer les noms figurant dans les certificats publics.</li><li><strong><a href="https://github.com/projectdiscovery/subfinder" target="_blank" rel="noreferrer">Subfinder</a></strong> - Rassembler des sous-domaines à partir de sources passives.</li><li><strong><a href="https://github.com/owasp-amass/amass" target="_blank" rel="noreferrer">Amass</a></strong> - Cartographier la surface d&#39;exposition d&#39;un domaine.</li><li><strong><a href="https://github.com/elceef/dnstwist" target="_blank" rel="noreferrer">dnstwist</a></strong> - Repérer les domaines ressemblants et les tentatives de typosquatting.</li><li><strong><a href="https://dnsdumpster.com/" target="_blank" rel="noreferrer">DNSDumpster</a></strong> - Explorer gratuitement les enregistrements DNS et les sous-domaines.</li><li><strong><a href="https://github.com/mschwager/fierce" target="_blank" rel="noreferrer">Fierce</a></strong> - Effectuer une reconnaissance DNS de domaines.</li><li><strong><a href="https://securitytrails.com/dns-trails" target="_blank" rel="noreferrer">SecurityTrails</a></strong> - Consulter des données DNS et leurs évolutions.</li><li><strong><a href="https://bgp.tools/" target="_blank" rel="noreferrer">BGP.tools</a></strong> - Identifier les annonces BGP et les réseaux associés.</li><li><strong><a href="https://lookup.icann.org/" target="_blank" rel="noreferrer">ICANN Lookup</a></strong> - Consulter les informations d&#39;enregistrement disponibles.</li><li><strong><a href="https://github.com/lanmaster53/recon-ng" target="_blank" rel="noreferrer">Recon-ng</a></strong> - Organiser les recherches OSINT dans un framework modulaire.</li><li><strong><a href="https://github.com/s0md3v/Photon" target="_blank" rel="noreferrer">Photon</a></strong> - Explorer un site Web et en extraire des URL et des données publiques.</li></ul><h2 id="infrastructure-et-cybermenaces" tabindex="-1">Infrastructure et cybermenaces <a class="header-anchor" href="#infrastructure-et-cybermenaces" aria-label="Permalink to &quot;Infrastructure et cybermenaces&quot;">​</a></h2><ul><li><strong><a href="https://www.shodan.io/" target="_blank" rel="noreferrer">Shodan</a></strong> - Rechercher les services Internet indexés.</li><li><strong><a href="https://search.censys.io/" target="_blank" rel="noreferrer">Censys</a></strong> - Explorer les hôtes, certificats et services connus.</li><li><strong><a href="https://www.virustotal.com/" target="_blank" rel="noreferrer">VirusTotal</a></strong> - Recouper IP, domaines, URL et empreintes de fichiers.</li><li><strong><a href="https://urlscan.io/" target="_blank" rel="noreferrer">urlscan.io</a></strong> - Examiner les observations publiques de pages et URL.</li><li><strong><a href="https://securityheaders.com/" target="_blank" rel="noreferrer">Security Headers</a></strong> - Analyser les en-têtes HTTP de sécurité d&#39;un site.</li><li><strong><a href="https://www.abuseipdb.com/" target="_blank" rel="noreferrer">AbuseIPDB</a></strong> - Consulter les signalements associés à une adresse IP.</li><li><strong><a href="https://otx.alienvault.com/" target="_blank" rel="noreferrer">AlienVault OTX</a></strong> - Recouper des indicateurs de compromission.</li><li><strong><a href="https://urlhaus.abuse.ch/" target="_blank" rel="noreferrer">URLhaus</a></strong> - Rechercher des URL associées à la diffusion de malware.</li><li><strong><a href="https://threatfox.abuse.ch/" target="_blank" rel="noreferrer">ThreatFox</a></strong> - Examiner les indicateurs publics de menace.</li></ul><h2 id="archives-et-publications" tabindex="-1">Archives et publications <a class="header-anchor" href="#archives-et-publications" aria-label="Permalink to &quot;Archives et publications&quot;">​</a></h2><ul><li><strong><a href="https://web.archive.org/" target="_blank" rel="noreferrer">Wayback Machine</a></strong> - Voir les versions conservées d&#39;une page Web.</li><li><strong><a href="https://archive.org/" target="_blank" rel="noreferrer">Internet Archive</a></strong> - Rechercher des pages, documents et contenus archivés.</li><li><strong><a href="https://www.documentcloud.org/" target="_blank" rel="noreferrer">DocumentCloud</a></strong> - Explorer des documents publics et leurs annotations.</li><li><strong><a href="https://datasetsearch.research.google.com/" target="_blank" rel="noreferrer">Google Dataset Search</a></strong> - Retrouver des jeux de données publics.</li><li><strong><a href="https://github.com/search" target="_blank" rel="noreferrer">GitHub Search</a></strong> - Retrouver projets, dépôts et discussions indexés.</li></ul><h2 id="personnes-et-documents-publics" tabindex="-1">Personnes et documents publics <a class="header-anchor" href="#personnes-et-documents-publics" aria-label="Permalink to &quot;Personnes et documents publics&quot;">​</a></h2><ul><li><strong><a href="https://hal.science/" target="_blank" rel="noreferrer">HAL</a></strong> - Publications scientifiques et affiliations.</li><li><strong><a href="https://orcid.org/" target="_blank" rel="noreferrer">ORCID</a></strong> - Identifiants et profils de chercheurs publics.</li><li><strong><a href="https://scholar.google.com/" target="_blank" rel="noreferrer">Google Scholar</a></strong> - Publications et citations.</li><li><strong><a href="https://www.legifrance.gouv.fr/" target="_blank" rel="noreferrer">Legifrance</a></strong> - Textes et décisions accessibles publiquement.</li><li><strong><a href="https://data.bnf.fr/" target="_blank" rel="noreferrer">Data BnF</a></strong> - Notices d&#39;auteurs et publications.</li></ul><h2 id="images-videos-et-geolocalisation" tabindex="-1">Images, vidéos et géolocalisation <a class="header-anchor" href="#images-videos-et-geolocalisation" aria-label="Permalink to &quot;Images, vidéos et géolocalisation&quot;">​</a></h2><ul><li><strong><a href="https://lens.google.com/" target="_blank" rel="noreferrer">Google Lens</a></strong> - Retrouver des images ressemblantes et éléments visuels.</li><li><strong><a href="https://tineye.com/" target="_blank" rel="noreferrer">TinEye</a></strong> - Rechercher les copies publiques d&#39;une image.</li><li><strong><a href="https://exiftool.org/" target="_blank" rel="noreferrer">ExifTool</a></strong> - Lire les métadonnées d&#39;images et de documents.</li><li><strong><a href="https://bellingcat.gitbook.io/toolkit" target="_blank" rel="noreferrer">Bellingcat Toolkit</a></strong> - Recouper lieux, médias et informations publiques.</li><li><strong><a href="https://earth.google.com/web/" target="_blank" rel="noreferrer">Google Earth</a></strong> - Comparer des vues de terrain et des repères géographiques.</li><li><strong><a href="https://www.openstreetmap.org/" target="_blank" rel="noreferrer">OpenStreetMap</a></strong> - Comparer rues, bâtiments et points d&#39;intérêt.</li></ul><h2 id="entreprises-et-registres" tabindex="-1">Entreprises et registres <a class="header-anchor" href="#entreprises-et-registres" aria-label="Permalink to &quot;Entreprises et registres&quot;">​</a></h2><ul><li><strong><a href="https://annuaire-entreprises.data.gouv.fr/" target="_blank" rel="noreferrer">Annuaire des entreprises</a></strong> - Vérifier les données des sociétés et établissements français.</li><li><strong><a href="https://opencorporates.com/" target="_blank" rel="noreferrer">OpenCorporates</a></strong> - Explorer les registres d&#39;entreprises de plusieurs pays.</li><li><strong><a href="https://www.pappers.fr/" target="_blank" rel="noreferrer">Pappers</a></strong> - Consulter les informations légales publiques d&#39;entreprises françaises.</li></ul><h2 id="methodes-rapports-et-referentiels" tabindex="-1">Méthodes, rapports et référentiels <a class="header-anchor" href="#methodes-rapports-et-referentiels" aria-label="Permalink to &quot;Méthodes, rapports et référentiels&quot;">​</a></h2><ul><li><strong><a href="https://github.com/jivoi/awesome-osint" target="_blank" rel="noreferrer">Awesome OSINT</a></strong> - Trouver une ressource complémentaire par domaine d&#39;investigation.</li><li><strong><a href="https://github.com/Jieyab89/OSINT-Cheat-sheet" target="_blank" rel="noreferrer">OSINT Cheat Sheet</a></strong> - Répertoire étendu de méthodes et d&#39;outils.</li><li><strong><a href="https://osintframework.com/" target="_blank" rel="noreferrer">OSINT Framework</a></strong> - Choisir un outil selon le type de renseignement.</li><li><strong><a href="https://gchq.github.io/CyberChef/" target="_blank" rel="noreferrer">CyberChef</a></strong> - Convertir et décoder des données.</li><li><strong><a href="https://attack.mitre.org/" target="_blank" rel="noreferrer">MITRE ATT&amp;CK</a></strong> - Relier des indices cyber aux techniques documentées.</li></ul>',25)]))}const f=r(o,[["render",n]]);export{p as __pageData,f as default};
